t.script:
                var ACCESS_TOKEN = '';
                var ORDER_ID     = ;

                /* ── CSRF token: works for both logged-in and public users ── */
                function getCsrf() {
                    /* Try Odoo JS object first, then meta tag fallback */
                    if (typeof odoo !== 'undefined' && odoo.csrf_token) return odoo.csrf_token;
                    var m = document.querySelector('meta[name="csrf-token"]');
                    if (m) return m.getAttribute('content');
                    /* Last resort: scrape from Odoo's hidden input if present */
                    var inp = document.querySelector('input[name="csrf_token"]');
                    return inp ? inp.value : '';
                }

                /* ── Modal helpers ── */
                function openApproveModal() { document.getElementById('modal-approve').classList.add('active'); }
                function openEditModal()    { document.getElementById('modal-edit').classList.add('active'); }
                function openCancelModal()  { document.getElementById('modal-cancel').classList.add('active'); }
                function closeModals() {
                    ['modal-approve','modal-edit','modal-cancel'].forEach(function(id){
                        document.getElementById(id).classList.remove('active');
                    });
                }

                /* ── Replace the entire card with a full-screen result ── */
                function showFullPageResult(success, heading, body, subtext) {
                    var icon  = success ? '✅' : '❌';
                    var color = success ? '#16a34a' : '#dc2626';
                    var bg    = success ? '#f0fdf4' : '#fef2f2';
                    var border= success ? '#bbf7d0' : '#fecaca';
                    document.querySelector('.pf-card').innerHTML =
                        '
' +
                        '
' + icon + '' +
                        '
' + heading + '' +
                        '
' + body + '' +
                        (subtext ? '
' + subtext + '' : '') +
                        '';
                    /* Close any open modals */
                    closeModals();
                    /* Scroll to top so the message is visible */
                    window.scrollTo({top: 0, behavior: 'smooth'});
                }

                /* ── POST helper ── */
                function post(data) {
                    var fd = new FormData();
                    fd.append('access_token', ACCESS_TOKEN);
                    fd.append('csrf_token', getCsrf());
                    for (var k in data) fd.append(k, data[k]);
                    return fetch('/my/quotes/' + ORDER_ID + '/sign/submit', {
                        method: 'POST',
                        body: fd,
                        headers: {'X-Requested-With': 'XMLHttpRequest'}
                    }).then(function(resp) {
                        /* fetch resolves for ALL HTTP statuses — parse JSON regardless */
                        return resp.json().catch(function() {
                            /* Response was not JSON (e.g. redirect to HTML) */
                            return {error: 'Unexpected response from server (status ' + resp.status + ').'};
                        });
                    });
                }

                /* ── Approve ── */
                function submitApprove() {
                    var name    = document.getElementById('signer-name').value.trim();
                    var consent = document.getElementById('consent-check').checked;
                    if (!name)    { alert('Please enter your full name.'); return; }
                    if (!consent) { alert('Please check the consent box to confirm you are authorised.'); return; }

                    /* Loading state */
                    var btn = document.querySelector('#modal-approve .pf-btn-approve');
                    btn.disabled = true;
                    btn.textContent = 'Processing…';

                    post({action: 'approve', customer_name: name})
                        .then(function(r) {
                            if (r.success) {
                                showFullPageResult(
                                    true,
                                    'Approval Received — Thank You!',
                                    'Quotation ' + (r.order_name || '') + ' has been approved.
' +
                                    'Signed by ' + (r.customer_name || name) + ' on ' + (r.approved_at || '') + '.
' +
                                    'Our team will review the details and confirm the booking separately.',
                                    r.signature_hash ? 'Signature reference: ' + r.signature_hash : ''
                                );
                            } else if (r.error && r.error.indexOf('already been processed') !== -1) {
                                /* Second click after first succeeded */
                                showFullPageResult(
                                    true,
                                    'Approval Already Received',
                                    'This quotation has already been approved and is pending internal confirmation.',
                                    ''
                                );
                            } else {
                                btn.disabled = false;
                                btn.textContent = 'Confirm Signature';
                                closeModals();
                                showFullPageResult(false, 'Something went wrong',
                                    r.error || 'Please try again or contact PremaFirm directly.', '');
                            }
                        })
                        .catch(function(err) {
                            btn.disabled = false;
                            btn.textContent = 'Confirm Signature';
                            closeModals();
                            showFullPageResult(false, 'Network Error',
                                'Could not reach the server. Please check your connection and try again.', '');
                        });
                }

                /* ── Request Changes ── */
                function submitEdit() {
                    var note = document.getElementById('edit-note').value.trim();
                    if (!note) { alert('Please describe the changes you need.'); return; }
                    post({action: 'edit', edit_note: note})
                        .then(function(r) {
                            if (r.success) {
                                showFullPageResult(
                                    true,
                                    'Change Request Sent',
                                    'Our team will review your request and respond via WhatsApp shortly.',
                                    ''
                                );
                            } else {
                                closeModals();
                                showFullPageResult(false, 'Could not send request',
                                    r.error || 'Please contact us directly.', '');
                            }
                        })
                        .catch(function() {
                            closeModals();
                            showFullPageResult(false, 'Network Error',
                                'Could not reach the server. Please try again.', '');
                        });
                }

                /* ── Cancel ── */
                function submitCancel() {
                    var reason = document.getElementById('cancel-reason').value.trim();
                    post({action: 'cancel', cancel_reason: reason})
                        .then(function(r) {
                            if (r.success) {
                                showFullPageResult(
                                    true,
                                    'Quotation Cancelled',
                                    'Your cancellation has been received. We hope to work with you on a future shipment.',
                                    ''
                                );
                            } else {
                                closeModals();
                                showFullPageResult(false, 'Could not cancel',
                                    r.error || 'Please contact us directly.', '');
                            }
                        })
                        .catch(function() {
                            closeModals();
                            showFullPageResult(false, 'Network Error',
                                'Could not reach the server. Please try again.', '');
                        });
                }
